def main():
    n = int(input())
    s = 0
    while n > 0:
        rest = n % 10
        if rest == 4 or rest == 7:
            s += 1
        n = n // 10
    if s == 4 or s == 7:
        print("YES")
    else:
        print("NO")

if __name__ == '__main__':
    main()

