def nearlyLucky(fortuna):
    count = 0

    while fortuna > 0:
        if fortuna % 10 == 4 or fortuna % 10 == 7:
            count += 1
        fortuna //= 10

    return count == 4 or count == 7


if __name__ == "__main__":
    fortuna = int(input())
    print("YES" if nearlyLucky(fortuna) else "NO")

def lucky(money):
    count = 0

    while money > 0:
        if money % 10 == 4 or money % 10 == 7:
            count += 1
        money //= 10

    return count in (4, 7)

if __name__ == "__main__":
    money = int(input())
    print("YES" if lucky(money) else "NO")

def nearlyLucky(money):
    count = 0
    while money > 0:
        if money % 10 == 4 or money % 10 == 7:
            count += 1
        money //= 10
    return count in (4, 7)

if __name__ == "__main__":
    money = int(input())
    print("YES" if nearlyLucky(money) else "NO")

def is_lucky(num):
    if num == 0:
        return False
    while num > 0:
        digit = num % 10
        if digit != 4 and digit != 7:
            return False
        num //= 10
    return True

def is_nearly_lucky(num):
    count = 0
    while num > 0:
        digit = num % 10
        if digit == 4 or digit == 7:
            count += 1
        num //= 10
