def findlucky(n):
    cnt = 0
    while n > 0:
        d = n % 10
        if d == 4 or d == 7:
            cnt += 1
        n //= 10

    if cnt == 0:
        return "NO"

    while cnt > 0:
        d = cnt % 10
        if d != 4 and d != 7:
            return "NO"
        cnt //= 10

    return "YES"

