import sys


def inp():
    return int(input())


def inlt():
    return list(map(int, input().split()))


def int_to_arr():
    return list(map(int, str(input()).strip()))


def insr():
    return input().strip()


def out(x):
    sys.stdout.write(str(x) + "\n")


def main():
    input_string = int_to_arr()
    count = 0

    for i in input_string:
        if i in [4, 7]:
            count += 1

    out("YES" if count == 4 or count == 7 else "NO")


if __name__ == "__main__":
    main()

